function notify(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))}
async function deriveKey(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function sha(text,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(text),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function loadLocal(key){const raw=localStorage.getItem(KEYS.data);if(!raw)return null;const box=JSON.parse(raw);if(box?.v===1&&box.iv&&box.data){if(!key)throw Error('Desbloquea el respaldo cifrado una última vez.');const iv=Uint8Array.from(atob(box.iv),c=>c.charCodeAt(0)),data=Uint8Array.from(atob(box.data),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv},key,data)))}return box}
function saveLocal(){if(!userData)return;localStorage.setItem(KEYS.data,JSON.stringify(userData));localStorage.removeItem(KEYS.salt);localStorage.removeItem(KEYS.hash);dataKey=null}
async function pushCloud(){if(!cloudReady||!cloudCanEdit||cloudSaving||!userData)return;cloudSaving=true;const snapshot=JSON.stringify(userData);try{const r=await fetch('/api/content-data',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot,cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo sincronizar.');cloudRevision=r.headers.get('ETag')||`"${d.etag||''}"`;const label=$('.privacy-label');if(label)label.innerHTML='<i></i> SINCRONIZADO EN LA NUBE';const baseNote=$('.brand-base-save');if(baseNote)baseNote.textContent='Base guardada y sincronizada en la nube.'}catch(error){const label=$('.privacy-label');if(label)label.innerHTML='<i></i> PENDIENTE DE SINCRONIZAR';const baseNote=$('.brand-base-save');if(baseNote)baseNote.textContent='Cambio guardado en este navegador; falta sincronizarlo con la nube.';console.error(error)}finally{cloudSaving=false;if(Date.now()-lastLocalChange<1000){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(pushCloud,1200)}}}
function save(){if(!userData)return;saveLocal();if(!cloudCanEdit)return;lastLocalChange=Date.now();if(cloudReady){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(pushCloud,700)}}
function composeScript(s){return [s.hook,s.outline,s.cta].map(x=>String(x||'').trim()).filter(Boolean).join('\n\n')}
function generateGuion(hook,format,angle){const h=String(hook||'').replace(/[.!?]+$/,'').trim();const rawAngle=String(angle||'');const dev=rawAngle.replace(/^(Idea para desarrollar|Idea principal|Tomas sugeridas|Desarrolla|Desarrolla esta idea)[:\s]*/i,'').split(/[.;]/)[0].trim().slice(0,130)||'Y eso cambia todo lo que pensabas saber sobre el tema';const fmt=String(format||'').trim();if(fmt==='B-roll + voz en off'){return[`"${h}." (B-roll: toma de contexto general, 2 seg)`,`"${dev}." (B-roll: manos en teclado o tarea relacionada, 1.5 seg)`,`"La parte que nadie muestra es la que más enseña." (B-roll: café, caminata o pausa, 1.5 seg)`,`"Todavía estoy en ese proceso." (B-roll: pantalla con trabajo en progreso, 1.5 seg)`,`"Pero eso es lo que quiero documentar." (B-roll: cierre con toma amplia, 1 seg)`].join('\n')}if(fmt==='Green screen'){return[`"${h}." (Talking head directo a cámara)`,`"${dev}." (Green screen: dato o pantalla relevante de fondo)`,`"Cuando ves los números reales, el problema queda claro." (Green screen: gráfico o captura)`,`"No es falta de herramientas; es falta de enfoque." (Talking head)`,`"Y esto es lo que estoy intentando cambiar." (Green screen: pantalla del proceso o solución)`].join('\n')}return[`"${h}." (Talking head directo a cámara)`,`"${dev}." (Talking head)`,`"La diferencia está en lo que haces antes de que nadie te vea hacerlo." (Talking head)`,`"Yo lo estoy aprendiendo mientras construyo." (Talking head)`,`"Y eso es lo que hace que valga la pena mostrarlo." (Talking head, cierre)`].join('\n')}
