function initLocal(data=null){userData=data||{stories:[],customIdeas:[],scripts:[],hooks:[],archivedHooks:[],brollIdeas:[],metrics:[],news:[],uploadedVideos:[],profileContext:'',saasContext:'',lastIgSync:0};for(const k of ['stories','customIdeas','scripts','hooks','archivedHooks','brollIdeas','metrics','news','uploadedVideos','patterns'])if(!Array.isArray(userData[k]))userData[k]=[];if(!userData.brandBase||typeof userData.brandBase!=='object'||Array.isArray(userData.brandBase))userData.brandBase={};userData.hooks=userData.hooks.filter(h=>h.status!=='discarded');for(const group of [userData.hooks,userData.scripts,userData.metrics,userData.storyIdeas||[]])for(const item of group)if(item.pillar==='automation')item.pillar='business';mergeMindsetIntoPersonal();seedConnaiBuildingPublic();refreshCurrentBrandContext();saveHookCategoryFramework();replacePendingWithCuratedIdeas();topUpCuratedHooks();rotateHookCategories();for(const h of userData.hooks)if(String(h.hook||'').startsWith('Soy Benja, tengo 22 años'))h.format='B-roll + voz en off';const knownUploads=new Set(userData.uploadedVideos.map(v=>String(v.instagramId||v.id)));for(const m of userData.metrics){if(!m.instagramId||!m.date||knownUploads.has(String(m.instagramId)))continue;userData.uploadedVideos.push({instagramId:String(m.instagramId),publishedAt:`${m.date}T12:00:00Z`,permalink:m.permalink||'',caption:m.title||''});knownUploads.add(String(m.instagramId))}for(const s of userData.scripts){const oldBody=s.body,previous=s.productionStatus||({published:'publicado',recorded:'grabado'}[s.status]||'');if(previous==='grabado'||previous==='publicado')s.productionStatus=previous;else if(['ready','draft','production','por_grabar'].includes(previous))s.productionStatus=oldBody?.trim()?'por_grabar':'guionizando';else if(previous==='guionizando')s.productionStatus='guionizando';else s.productionStatus=oldBody?.trim()?'por_grabar':'guionizando';if(s.productionStatus==='guionizando'&&!oldBody?.trim())s.body=composeScript(s)}if(!('profileContext'in userData))userData.profileContext='';if(!('saasContext'in userData))userData.saasContext='';cleanBrandHooks();removeScreenShareHooks();removeAiHooks();seedFreshHookBatch();appendSecondHookBatch();appendThirdHookBatch();seedPerformanceIntro();seedPerformanceBatch();seedFiftyPerPillar();refreshPendingHookStructures();refreshPendingHookDirections();refreshHookIdeasAndUniqueness();refreshGreenScreenVisuals();refreshBrollNarrative();refreshFormatPositioning();updateBrandArchitecture();dedupePendingHooks();fillHookQuotas();dedupePendingHooks();refreshSpecificHookIdeas()}
function seedPerformanceBatch(){if(userData._performanceBatchVersion===1)return;const hooks=['Así se ve mi punto de partida para construir un físico más estético y atlético.','Estoy entrenando jiu jitsu todos los días, pero todavía me falta construir el físico que quiero.','Esto es lo que como cuando tengo que estudiar, trabajar y entrenar.','Volver a correr después de haber llegado a 10 kilómetros se siente así.','El físico que tenía, el que perdí y el que estoy intentando recuperar.','No quiero solamente verme fuerte; quiero rendir mejor en el tatami.','Así organizo mi alimentación cuando el día está lleno de reuniones y clases.','Mi objetivo no es ser fisicoculturista: quiero un cuerpo atlético que funcione.','Un día comiendo rápido mientras intento mejorar mi físico y construir negocios.','Lo que el jiu jitsu me está enseñando sobre mi condición física.','Estoy empezando running de nuevo y esta es la razón.','La diferencia entre entrenar para verse bien y entrenar para rendir.','Así se ve intentar mejorar tu físico cuando no tienes una rutina perfecta.','No estoy buscando un cambio rápido; estoy documentando cómo vuelvo a sentirme fuerte.','Jiu jitsu, comida rápida y una meta física que todavía está lejos.','Lo que cambió cuando dejé de pensar solo en masa muscular.','Estoy construyendo un físico que me guste mirar y que me ayude a competir.','Así intento combinar BJJ, running, gimnasio y una vida ocupada.','El cansancio de entrenar todos los días mientras persigues otras metas.'];for(let i=0;i<hooks.length;i++)userData.hooks.push({id:`performance-${Date.now()}-${i}`,pillar:'performance',format:'B-roll + voz en off',hook:hooks[i],angle:'Tomas de entrenamiento, comidas, cuerpo, trayectos y recuperación; cuenta qué estás intentando mejorar, qué te cuesta y cómo se conecta con tu objetivo físico y deportivo.',framework:'Transformación física documentada',status:'new',createdAt:new Date().toISOString()});userData._performanceBatchVersion=1;userData._needsCloudSeed=true;saveLocal()}
