function enterStudio(){ $('#lockTitle').innerHTML='Habilita la<br><span>edición.</span>';$('#lockCopy').textContent='La consulta es pública. Autoriza este navegador para editar y sincronizar cambios.';$('#lockForm label').textContent='Clave de edición';$('#lockSubmit').innerHTML='Habilitar edición <span>→</span>';$('#localPin').setAttribute('autocomplete','one-time-code');$('#localPin').setAttribute('placeholder','Clave de edición');$('#localPin').removeAttribute('minlength');$('#lockScreen').classList.remove('hidden');$('#lockMessage').textContent='';$('#localPin').value=''}
function showApp(){ $('#lockScreen').classList.add('hidden');$('#studioApp').classList.remove('hidden');const edit=$('#editStudy'),label=$('.privacy-label');if(edit)edit.classList.toggle('hidden',cloudCanEdit);if(label)label.innerHTML=`<i></i> ${cloudCanEdit?'SINCRONIZADO EN LA NUBE':'VISTA PÚBLICA'}`;renderView();checkIgConfig();scheduleIgSync();scheduleCloudSync()}
function applyReadOnlyUI(){const edit=$('#editStudy'),importButton=$('#importData');if(edit)edit.classList.toggle('hidden',cloudCanEdit);if(cloudCanEdit){importButton?.removeAttribute('disabled');importButton?.removeAttribute('title');return}$('#viewContainer')?.querySelectorAll('button,input,textarea,select').forEach(el=>{if(el.matches('.content-tab')||el.id==='metricWindow'||el.id==='refreshNews')return;el.disabled=true});importButton?.setAttribute('disabled','');importButton?.setAttribute('title','Habilita la edición para importar un respaldo')}
function requestEdit(){if(!cloudCanEdit)enterStudio()}
window.addEventListener('storage',event=>{if(event.key===KEYS.data&&userData&&!cloudReady){try{initLocal(JSON.parse(event.newValue));renderView()}catch{}}});
async function fetchCloud(){const r=await fetch('/api/content-data',{cache:'no-store'});if(r.status===404)return {empty:true};const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo cargar el estudio.');return {data,revision:r.headers.get('ETag')||''}}
async function scheduleCloudSync(){if(cloudSyncTimer)clearInterval(cloudSyncTimer);cloudSyncTimer=setInterval(async()=>{if(document.visibilityState!=='visible'||!cloudReady||cloudSaving||cloudSaveTimer||Date.now()-lastLocalChange<2500)return;try{const remote=await fetchCloud();if(remote.data&&remote.revision&&remote.revision!==cloudRevision){initLocal(remote.data);saveLocal();cloudRevision=remote.revision;renderView();notify('Estudio actualizado desde tu otro dispositivo.')}}catch(error){console.error(error)}},20000)}
async function authorizeAndLoad(key){const msg=$('#lockMessage');msg.textContent='Verificando acceso…';const auth=await fetch('/api/content-auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key})}),authData=await auth.json();if(!auth.ok)throw Error(authData.error||'No se pudo autorizar este dispositivo.');cloudCanEdit=true;const cloud=await fetchCloud();if(cloud.data){initLocal(cloud.data);cloudRevision=cloud.revision;saveLocal();if(userData._needsCloudCleanup||userData._needsCloudSeed){delete userData._needsCloudCleanup;delete userData._needsCloudSeed;cloudReady=true;save()}}else{const raw=localStorage.getItem(KEYS.data);if(raw){const parsed=JSON.parse(raw);if(parsed?.v===1&&parsed.iv&&parsed.data)throw Error('Este navegador tiene un respaldo local cifrado. Restaura primero el respaldo desde otro dispositivo.');initLocal(parsed)}else initLocal();replaceCurrentHookBatch();saveLocal();cloudReady=true;await pushCloud()}cloudReady=true;showApp()}
function pillarName(p){return PILLARS[p]||PILLARS.unclassified}
function setView(v){activeView=v;if(v==='content'&&!['writing','ready','done'].includes(contentTab))contentTab='writing';$$('.side-link').forEach(b=>b.classList.toggle('selected',b.dataset.view===v));renderView()}
function renderView(){if(!userData)return;if(activeView==='metrics'&&$('#viewContainer')){}if(activeView!=='metrics'&&contentTab==='hooks'){$$('.pillar-group').forEach((d,i)=>{if(d.open&&!hookUiState.pillars.includes(i))hookUiState.pillars.push(i)});$$('.format-group').forEach((d,i)=>{if(d.open&&!hookUiState.formats.includes(i))hookUiState.formats.push(i)})}const title=$('#pageTitle');if(title)title.textContent=activeView==='metrics'?`${monthlyVideoCount()} / ${monthlyVideoGoal()} Reels este mes`:'Contenido';$('#viewContainer').innerHTML=activeView==='metrics'?metricsView():contentView();if(activeView!=='metrics'&&contentTab==='hooks'){$$('.pillar-group').forEach((d,i)=>{d.open=hookUiState.pillars.includes(i)});$$('.format-group').forEach((d,i)=>{d.open=hookUiState.formats.includes(i)})}applyReadOnlyUI();if(activeView==='metrics')checkIgConfig();wireView()}
function isPovHook(h){return String(h.format||'').trim().toLowerCase()==='pov'}
function contentCounts(){return {hooks:userData.hooks.filter(h=>h.status==='new'&&!isPovHook(h)).length,ready:userData.scripts.filter(s=>s.productionStatus==='por_grabar').length,done:userData.scripts.filter(s=>['grabado','publicado'].includes(s.productionStatus)).length}}
function contentView(){const counts=contentCounts(),tabs=[['stories','Historias'],['broll','B-roll'],['hooks','Hooks',counts.hooks],['writing','Guionización'],['ready','Para grabar',counts.ready],['done','Grabado',counts.done],['news','Radar IA'],...(cloudCanEdit?[['brand','Base de marca']]:[])];return `<div class="content-tabs" role="tablist">${tabs.map(([key,label,count])=>`<button class="content-tab ${contentTab===key?'selected':''}" data-content-tab="${key}">${label}${count!==undefined?`<span class="tab-count">${count}</span>`:''}</button>`).join('')}</div>${contentTab==='hooks'?hooksView():contentTab==='writing'?writingView():contentTab==='ready'?readyView():contentTab==='done'?doneView():contentTab==='stories'?storiesView():contentTab==='broll'?brollView():contentTab==='news'?newsView():brandBaseView()}${userData.openScriptId?scriptReader(userData.scripts.find(s=>s.id===userData.openScriptId)):''}`}
function brandBaseView(){if(!cloudCanEdit)return '';return `<section class="view-panel brand-base-panel"><p class="eyebrow">CONTEXTO PRIVADO · SOLO PARA EL GENERADOR</p><h2>Base de marca personal</h2><p class="subcopy">Esta base orienta los pilares, formatos, audiencias y hooks. Completa también la oferta, LinkedIn y los dolores de cada audiencia para que las propuestas no dependan de suposiciones. No modifica tus guiones existentes.</p><p class="brand-base-private"><span>●</span> Esta base solo se entrega a sesiones autorizadas para editar.</p><div class="brand-base-groups">${BRAND_BASE_GROUPS.map((group,index)=>`<details class="brand-base-group" ${group.open?'open':''}><summary><b>${esc(group.title)}</b><span>Editar contexto</span></summary><div class="brand-base-fields">${group.fields.map(([key,label])=>`<label>${esc(label)}<textarea data-brand-field="${key}" rows="${['story','saas','audience','startingAudience','ownerAudience','offer','linkedin','pillars','voice','hookFrameworks','boundaries','updates'].includes(key)?6:4}" placeholder="Completa este contexto">${esc(userData.brandBase?.[key]||'')}</textarea></label>`).join('')}</div></details>`).join('')}</div><p class="brand-base-save" aria-live="polite">Los cambios se guardan automáticamente en el estudio.</p></section>`}
function syncBrandContexts(){const base=userData.brandBase||{};userData.profileContext=BRAND_PROFILE_FIELDS.map(key=>`${key.toUpperCase()}\n${base[key]||''}`).join('\n\n');userData.saasContext=`SAAS Y ETAPA ACTUAL\n${base.saas||''}\n\nAUDIENCIA\n${base.audience||''}\n\nLÍMITES\n${base.boundaries||''}`}
function hookFormat(h){const raw=String(h.format||'').trim();return FORMAT_ALIASES[raw.toLowerCase()]||VIDEO_FORMATS.find(x=>x.name.toLowerCase()===raw.toLowerCase())?.name||'Sin formato'}
function displayPillar(key){if(key==='founder')return 'mindset';if(key==='automation')return 'business';return PILLARS[key]?key:'unclassified'}
function hooksView(){const fresh=userData.hooks.filter(h=>h.status==='new'&&!isPovHook(h));const formatGroups=VIDEO_FORMATS.map(fmt=>({...fmt,items:fresh.filter(h=>hookFormat(h)===fmt.name)})).filter(g=>g.items.length);const unclassified=fresh.filter(h=>!VIDEO_FORMATS.some(f=>f.name===hookFormat(h)));if(unclassified.length)formatGroups.push({name:'Sin formato',description:'Hooks sin formato asignado.',items:unclassified});return `<section class="view-panel"><p class="eyebrow">IDEAS PARA REVISAR · ${fresh.length} PENDIENTES</p><h2>Hooks por formato</h2><p class="subcopy">Abre el formato que quieres revisar. Cada bloque muestra su cantidad de hooks.</p><div class="pillar-groups">${formatGroups.map(group=>`<details class="format-group"><summary><span><b>${esc(group.name)}</b><small>${esc(group.description||'')} · ${group.items.length} hooks</small></span><strong>${group.items.length}</strong></summary><div class="hook-list">${group.items.map(hookCard).join('')}</div></details>`).join('')||'<p class="empty-state">No hay hooks para revisar.</p>'}</div></section>`}
function hookCard(h){const format=hookFormat(h),rawDirection=h.angle||h.idea||'Idea para desarrollar',direction=format==='Green screen'?rawDirection.replace(/^Idea principal:\s*/,''):rawDirection,label=format==='Green screen'?'':'Idea principal: ';return `<article class="hook-card"><div class="hook-card-top"><span class="pillar-pill">${esc(pillarName(displayPillar(h.pillar)))}</span><span class="pillar-pill hook-format-pill">${esc(format)}</span>${h.hookCategory?`<span class="pillar-pill hook-category-pill">${esc(h.hookCategory)}</span>`:''}<span class="story-meta">NUEVO</span></div><h3>${esc(h.hook)}</h3><p class="hook-context">${[h.audience,h.framework].filter(Boolean).map(esc).join(' · ')||'Idea lista para desarrollar'}</p><p class="hook-angle">${label}${format==='B-roll + voz en off'?`(${esc(direction)})`:esc(direction)}</p><div class="hook-actions"><button class="button button-lime approve-hook" data-id="${esc(h.id)}">Aprobar</button><button class="text-button delete-hook" data-id="${esc(h.id)}">Eliminar</button></div></article>`}
function writingView(){const items=userData.scripts.filter(s=>s.productionStatus==='guionizando');return `<section class="view-panel"><p class="eyebrow">DESARROLLA LA IDEA</p><h2>Guionización</h2><p class="subcopy">Desarrolla un hook aprobado o escribe un guion libre desde cero.</p><details class="free-script-composer"><summary><span class="eyebrow">BLOC DE NOTAS</span><b>Escribir un guion libre</b><small>Abre para escribir sin estructura</small></summary><div class="free-script-fields"><label>Título para identificarlo <span>(opcional)</span><input id="freeScriptTitle" type="text" placeholder="Ej. Lo que aprendí esta semana"></label><label>Formato <span class="required-field">(obligatorio)</span><select id="freeScriptFormat" required><option value="">Selecciona un formato</option>${VIDEO_FORMATS.map(f=>`<option value="${esc(f.name)}">${esc(f.name)}</option>`).join('')}</select></label><label>Tu guion<textarea id="freeScriptBody" rows="7" placeholder="Escribe aquí tus ideas, frases o el guion completo…"></textarea></label><button class="button button-lime" id="saveFreeScript">Guardar en Guionización</button></div></details><div class="writing-list">${items.map(writingCard).join('')||'<p class="empty-state">Tus borradores y hooks aprobados aparecerán aquí.</p>'}</div></section>`}
function contentMetadata(s){return [s.audience,s.format,s.hookCategory?`Categoría: ${s.hookCategory}`:'',s.framework].filter(Boolean).map(esc).join(' · ')}
function writingCard(s){if(s.freeform)return `<article class="writing-card free-writing-card" data-script-card="${esc(s.id)}"><label>Título<input class="free-writing-title" data-id="${esc(s.id)}" value="${esc(s.title||'Guion libre')}" placeholder="Título del guion"></label><label class="free-writing-body">Bloc de notas<textarea data-script-field="body" data-id="${esc(s.id)}" rows="12" placeholder="Escribe aquí tu guion…">${esc(s.body||'')}</textarea></label><div class="script-actions"><button class="button button-lime send-to-ready" data-id="${esc(s.id)}">Enviar a Para grabar</button><button class="text-button delete-script" data-id="${esc(s.id)}">Eliminar</button></div></article>`;if('referenceGuion' in s){return `<article class="writing-card" data-script-card="${esc(s.id)}">${contentMetadata(s)?`<p class="muted-intro">${contentMetadata(s)}</p>`:''}<div class="writing-card-two-col"><div><div class="writing-col-label">Guion de referencia</div>${s.referenceGuion?`<div class="reference-guion">${esc(s.referenceGuion)}</div>`:`<div class="reference-guion" style="display:flex;flex-direction:column;gap:10px;align-items:flex-start"><span style="color:var(--muted);font-size:0.85rem">Generando guion de referencia...</span><button class="button button-outline generate-guion" data-id="${esc(s.id)}">Generar ahora</button></div>`}</div><div><div class="writing-col-label">Tu versión</div><textarea data-script-field="body" data-id="${esc(s.id)}" rows="12" placeholder="Escribe tu versión del guion aquí. Usá el de referencia como guía.">${esc(s.body||'')}</textarea></div></div><div class="script-actions" style="justify-content:center"><button class="button button-lime send-to-ready" data-id="${esc(s.id)}">Enviar a Para grabar</button><button class="text-button delete-script" data-id="${esc(s.id)}">Eliminar</button></div></article>`}
return `<article class="writing-card" data-script-card="${esc(s.id)}"><div class="writing-parts">${contentMetadata(s)?`<p class="muted-intro">${contentMetadata(s)}</p>`:''}<label>Hook<textarea data-script-field="hook" data-id="${esc(s.id)}" rows="3">${esc(s.hook||'')}</textarea></label><label>Desarrollo<textarea data-script-field="outline" data-id="${esc(s.id)}" rows="7" placeholder="Cuenta el contexto, qué pasó y qué aprendiste.">${esc(s.outline||'')}</textarea></label><label>Cierre<textarea data-script-field="cta" data-id="${esc(s.id)}" rows="3" placeholder="Una idea final o invitación natural.">${esc(s.cta||'')}</textarea></label></div><label class="full-script-field">Guion completo<textarea data-script-field="body" data-id="${esc(s.id)}" rows="13" placeholder="Se completa automáticamente con Hook, Desarrollo y Cierre. También puedes editarlo.">${esc(s.body||'')}</textarea><small class="script-auto-note">Se arma solo con los tres campos de la izquierda; puedes ajustar el texto aquí.</small></label><div class="script-actions"><button class="button button-lime send-to-ready" data-id="${esc(s.id)}">Enviar a Para grabar</button><button class="text-button delete-script" data-id="${esc(s.id)}">Eliminar</button></div></article>`}
function readyView(){const all=userData.scripts.filter(s=>s.productionStatus==='por_grabar'),formats=[...new Set(all.map(hookFormat))].sort(),items=readyFormatFilter==='all'?all:all.filter(s=>hookFormat(s)===readyFormatFilter);return `<section class="view-panel"><p class="eyebrow">${items.length} GUIONES LISTOS</p><div class="stage-heading-row"><div><h2>Para grabar <span class="stage-count">${items.length}</span></h2><p class="subcopy">Filtra rápidamente por el formato que vas a grabar.</p></div><label class="date-filter-label">Formato<select id="readyFormatFilter"><option value="all" ${readyFormatFilter==='all'?'selected':''}>Todos los formatos (${all.length})</option>${formats.map(f=>`<option value="${esc(f)}" ${readyFormatFilter===f?'selected':''}>${esc(f)} (${all.filter(s=>hookFormat(s)===f).length})</option>`).join('')}</select></label></div><div class="ready-list">${items.map(s=>`<button class="ready-card open-script" data-id="${esc(s.id)}"><span class="pillar-pill">${esc(pillarName(s.pillar))}</span><span class="pillar-pill hook-format-pill">${esc(hookFormat(s))}</span><b>${esc(s.hook||s.title)}</b>${hookFormat(s)==='Green screen'?`<label class="green-bg-check" title="Marca cuando el fondo esté preparado"><input type="checkbox" class="green-background-check" data-id="${esc(s.id)}" ${s.backgroundReady?'checked':''}> Fondo listo</label>`:''}</button>`).join('')||'<p class="empty-state">No hay guiones listos en este formato.</p>'}</div></section>`}
function localDateKey(value){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return '';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);return `${parts.find(x=>x.type==='year')?.value}-${parts.find(x=>x.type==='month')?.value}-${parts.find(x=>x.type==='day')?.value}`}
function doneDate(s){return s.productionStatus==='publicado'?(s.publishedAt||s.recordedAt||''):(s.recordedAt||'')}
function donePeriodItems(items,period){const today=localDateKey(Date.now()),dated=items.map(s=>({s,key:localDateKey(doneDate(s))}));if(period==='undated')return dated.filter(x=>!x.key).map(x=>x.s);if(period==='today')return dated.filter(x=>x.key===today).map(x=>x.s);if(period==='yesterday'){const d=new Date(`${today}T12:00:00-03:00`);d.setDate(d.getDate()-1);return dated.filter(x=>x.key===localDateKey(d)).map(x=>x.s)}if(period==='week'){const d=new Date(`${today}T12:00:00-03:00`);d.setDate(d.getDate()-6);const from=localDateKey(d);return dated.filter(x=>x.key&&x.key>=from&&x.key<=today).map(x=>x.s)}if(period==='month')return dated.filter(x=>x.key&&x.key.slice(0,7)===today.slice(0,7)).map(x=>x.s);return items}
function doneView(){const all=userData.scripts.filter(s=>['grabado','publicado'].includes(s.productionStatus)),period=userData.donePeriod||'all',items=donePeriodItems(all,period);return `<section class="view-panel"><p class="eyebrow">${all.length} VIDEOS EN EL HISTORIAL</p><div class="stage-heading-row"><div><h2>Grabado <span class="stage-count">${all.length}</span></h2><p class="subcopy">Revisa cuánto grabaste por día o periodo. Los videos anteriores sin fecha aparecen bajo “Sin fecha”.</p></div><label class="date-filter-label">FILTRAR POR FECHA<select id="donePeriod"><option value="today" ${period==='today'?'selected':''}>Hoy</option><option value="yesterday" ${period==='yesterday'?'selected':''}>Ayer</option><option value="week" ${period==='week'?'selected':''}>Últimos 7 días</option><option value="month" ${period==='month'?'selected':''}>Este mes</option><option value="all" ${period==='all'?'selected':''}>Todo el historial</option><option value="undated" ${period==='undated'?'selected':''}>Sin fecha (${all.filter(s=>!localDateKey(doneDate(s))).length})</option></select></label></div><div class="period-result-count">${items.length} ${items.length===1?'video':'videos'} en este periodo</div><div class="ready-list">${items.map(s=>{const date=doneDate(s),label=date?new Date(date).toLocaleString('es-CL',{timeZone:'America/Santiago',dateStyle:'medium',timeStyle:date.includes('T')?'short':undefined}):'Fecha sin registrar';return `<button class="ready-card open-script" data-id="${esc(s.id)}"><span class="pillar-pill">${esc(pillarName(s.pillar))}</span><b>${esc(s.hook||s.title)}</b><small>${s.productionStatus==='publicado'?'Publicado':'Grabado'} · ${esc(label)}</small></button>`}).join('')||'<p class="empty-state">No hay videos en este periodo.</p>'}</div></section>`}
function scriptReader(s){if(!s)return '';const full=s.body?.trim()||[s.hook,s.outline,s.cta].filter(Boolean).join('\n\n');return `<div class="script-reader-backdrop" data-close-reader><section class="script-reader" role="dialog" aria-modal="true" aria-label="Guion editable"><span class="pillar-pill">${esc(pillarName(s.pillar))} · ${s.productionStatus==='publicado'?'PUBLICADO':s.productionStatus==='grabado'?'GRABADO':'LISTO PARA GRABAR'}</span><label class="reader-edit-label">HOOK<textarea class="reader-hook-editor" data-reader-field="hook" data-id="${esc(s.id)}" rows="2" aria-label="Editar hook">${esc(s.hook||s.title||'')}</textarea></label><label class="reader-edit-label">GUION COMPLETO<textarea class="reader-script-editor" data-reader-field="body" data-id="${esc(s.id)}" aria-label="Editar guion completo">${esc(full)}</textarea></label><p class="reader-edit-note" aria-live="polite">Tus cambios se guardan automáticamente en este navegador.</p>${s.productionStatus==='por_grabar'?`<div class="reader-actions"><button class="button button-lime mark-recorded" data-id="${esc(s.id)}">Grabado</button><button class="text-button delete-script" data-id="${esc(s.id)}">Eliminar</button></div>`:s.productionStatus==='grabado'?`<div class="reader-actions"><button class="button button-lime return-to-ready" data-id="${esc(s.id)}">Devolver a Para grabar</button></div>`:''}</section></div>`}
function storiesView(){const ideas=storyIdeasCache.length?storyIdeasCache:(storyIdeasCache=storyIdeas());const saved=userData.storyIdeas||[];return `<section class="view-panel"><p class="eyebrow">HISTORIAS NATURALES · TU DÍA A DÍA</p><h2>Qué podrías compartir hoy</h2><p class="subcopy">No necesitas inventar una historia. Muestra una escena real y agrega una frase: qué estás haciendo, qué estás pensando o qué aprendiste.</p><div class="story-routine"><b>Rutina simple de historias</b><span>1. Momento real</span><span>2. Contexto en una frase</span><span>3. Interacción: encuesta, pregunta o deslizador</span></div><button class="button button-lime" id="refreshStoryIdeas">Dame otras ideas</button><div class="story-suggestion-grid">${ideas.map((x,i)=>`<article class="story-suggestion"><span class="pillar-pill">${esc(pillarName(x.pillar))}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><button class="text-button save-story-idea" data-index="${i}">Guardar idea ↗</button></article>`).join('')}</div><h3 class="section-label">Ideas guardadas</h3><div class="saved-story-list">${saved.map((x,i)=>`<article class="saved-story"><span class="pillar-pill">${esc(pillarName(x.pillar))}</span><div><b>${esc(x.title)}</b><p>${esc(x.description)}</p></div><button class="text-button delete-story-idea" data-index="${i}">Quitar</button></article>`).join('')||'<p class="empty-state">Guarda aquí las ideas de historias que te sirvan.</p>'}</div></section>`}
