function monthKey(value){try{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit'}).formatToParts(new Date(value));return `${parts.find(x=>x.type==='year')?.value}-${parts.find(x=>x.type==='month')?.value}`}catch{return ''}}
function monthlyVideoGoal(){const now=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit'}).formatToParts(now),year=Number(parts.find(x=>x.type==='year')?.value),month=Number(parts.find(x=>x.type==='month')?.value);return new Date(year,month,0).getDate()*3}
function monthlyVideoCount(){const month=monthKey(Date.now());return new Set((userData.uploadedVideos||[]).filter(v=>monthKey(v.publishedAt||v.date)===month&&(v.isReel===true||v.mediaProductType==='REELS'||v.media_product_type==='REELS')).map(v=>String(v.instagramId||v.id))).size}
function monthlyChallengeView(){const count=monthlyVideoCount(),goal=monthlyVideoGoal(),left=Math.max(0,goal-count),percent=Math.min(100,Math.round(count/goal*100));return `<section class="monthly-challenge"><div class="monthly-challenge-copy"><p class="eyebrow">RETO DEL MES · DEL 1 AL ÚLTIMO DÍA</p><h2><strong>3</strong> Reels al día</h2><p>${count} de ${goal} Reels publicados este mes. ${left?`Te faltan ${left} para llegar a la meta.`:'¡Meta mensual cumplida! Sigue publicando.'} Instagram cuenta también los Reels que publicaste fuera del estudio.</p></div><div class="monthly-challenge-progress"><div class="monthly-progress-track" role="progressbar" aria-label="Progreso de Reels publicados este mes" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(goal,count)}"><span style="width:${percent}%"></span></div><small>${percent}% de la meta</small></div></section>`}
function metricWindow(){const days=Number($('#metricWindow')?.value??userData.metricWindow??15);if(!days)return getMetrics();const cutoff=new Date();cutoff.setDate(cutoff.getDate()-days);const key=cutoff.toISOString().slice(0,10);return getMetrics().filter(m=>(m.date||'')>=key)}
function getMetrics(){return userData.metrics||[]}
function available(m,k){if(m.source!=='instagram-api')return m[k]!==null&&m[k]!==undefined;if(Array.isArray(m.availableMetrics))return m.availableMetrics.includes(k);return ['views','reach','likes','comments'].includes(k)||Number(m[k])>0}
function sumAvailable(items,k){const got=items.filter(m=>available(m,k));return got.length?{value:got.reduce((a,m)=>a+(Number(m[k])||0),0),count:got.length}:{value:null,count:0}}
function numberText(n){return n===null||n===undefined?'—':Number(n).toLocaleString('es-CL')}
function median(numbers){const a=numbers.filter(Number.isFinite).sort((x,y)=>x-y);if(!a.length)return 0;const m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2}
function recomputePerformance(){autoLinkMetrics();const ms=userData.metrics||[],values=ms.filter(m=>available(m,"views")).map(m=>Number(m.views)).sort((a,b)=>a-b),mid=values.length?median(values):0;for(const m of ms){if(m.performanceLabel==="manual")continue;const v=Number(m.views)||0;m.performanceLabel=!values.length?"normal":v>=mid*1.6?"winner":v>=mid*1.15?"promising":v<mid*.55?"low":"normal";if(!m.hypothesis&&m.performanceLabel==="winner")m.hypothesis="Hipótesis: superó tu mediana; necesitamos más videos comparables para confirmar qué elemento causó el resultado."}}
