async function syncInstagram(){const el=$('#metricMessage');if(el)el.textContent='Sincronizando publicaciones…';try{const r=await fetch('/api/instagram-metrics',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo conectar.');const uploadMap=new Map((userData.uploadedVideos||[]).map(v=>[String(v.instagramId||v.id),v]));for(const video of d.videos||[]){const id=String(video.id),existing=uploadMap.get(id);if(existing)Object.assign(existing,{publishedAt:video.timestamp||existing.publishedAt,permalink:video.permalink||existing.permalink,caption:video.caption||existing.caption,mediaType:video.media_type,mediaProductType:video.media_product_type,isReel:video.media_product_type==='REELS'});else{const saved={instagramId:id,publishedAt:video.timestamp,permalink:video.permalink||'',caption:video.caption||'',mediaType:video.media_type,mediaProductType:video.media_product_type,isReel:video.media_product_type==='REELS'};userData.uploadedVideos.push(saved);uploadMap.set(id,saved)}}for(const x of d.media||[]){if(!x.insights)continue;const exists=userData.metrics.find(m=>m.instagramId===x.id),raw=x.insights,has=k=>Object.prototype.hasOwnProperty.call(raw,k),val=k=>has(k)?Number(raw[k]):null;const metrics={id:exists?.id||`IG${x.id}`,instagramId:x.id,title:(x.caption||'Reel sin título').slice(0,120),permalink:x.permalink||'',date:(x.timestamp||'').slice(0,10),platform:'instagram',pillar:exists?.pillar||'unclassified',objective:exists?.objective||'connection',duration:Number(x.video_duration||exists?.duration||0),views:val('views'),reach:val('reach'),likes:x.like_count===undefined?val('likes'):Number(x.like_count),comments:x.comments_count===undefined?val('comments'):Number(x.comments_count),saves:val('saved'),shares:val('shares'),followersGained:val('follows'),profileVisits:val('profile_visits'),avgWatch:has('ig_reels_avg_watch_time')?Number(raw.ig_reels_avg_watch_time)/1000:null,availableMetrics:[...['views','reach','likes','comments','saved','shares','follows','profile_visits','ig_reels_avg_watch_time'].filter(k=>has(k)).map(k=>({saved:'saves',follows:'followersGained',profile_visits:'profileVisits',ig_reels_avg_watch_time:'avgWatch'}[k]||k)),...(x.like_count===undefined?[]:['likes']),...(x.comments_count===undefined?[]:['comments'])],source:'instagram-api'};if(exists)Object.assign(exists,metrics);else userData.metrics.push(metrics)}userData.lastIgSync=Date.now();recomputePerformance();save();renderView();const msg=$('#metricMessage');if(msg)msg.textContent=`Instagram actualizado · ${d.media?.filter(x=>x.insights).length||0} publicaciones · ${monthlyVideoCount()} Reels este mes.`;notify('Instagram actualizado. El reto mensual cuenta todos tus Reels publicados.')}catch(err){if(el)el.textContent=err.message}}
