function scheduleIgSync(){if(igSyncTimer)clearInterval(igSyncTimer);const maybe=()=>{if(cloudCanEdit&&document.visibilityState==='visible'&&Date.now()-(userData?.lastIgSync||0)>3*60*60*1000)syncInstagram()};setTimeout(maybe,1600);igSyncTimer=setInterval(maybe,60*60*1000);document.addEventListener('visibilitychange',maybe,{once:false})}
