function exportJson(data,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function contentCalendarView(){const now=new Date(),year=now.getFullYear(),month=String(now.getMonth()+1).padStart(2,'0'),days=new Date(year,now.getMonth()+1,0).getDate(),rawItems=[...(userData.metrics||[]),...(userData.uploadedVideos||[])],items=[...new Map(rawItems.map(x=>[String(x.instagramId||x.id||x.permalink||x.publishedAt),x])).values()],byDay={};for(const item of items){const date=String(item.date||item.publishedAt||'').slice(0,10);if(date.startsWith(`${year}-${month}-`)){const day=Number(date.slice(8,10));(byDay[day]||(byDay[day]=[])).push(item)}}return `<section class="content-calendar"><div class="top-videos-heading"><h3>Calendario de publicaciones</h3><span>${now.toLocaleDateString('es-CL',{month:'long',year:'numeric'})}</span></div><div class="calendar-grid">${Array.from({length:days},(_,i)=>{const day=i+1,posts=byDay[day]||[];return `<div class="calendar-day ${posts.length?'has-posts':''}"><b>${day}</b>${posts.slice(0,2).map(x=>`<a href="${esc(x.permalink||'#')}" target="_blank" rel="noopener">${esc((x.title||x.caption||'Reel publicado').slice(0,30))}</a>`).join('')}</div>`}).join('')}</div></section>`}
function winnerSection(){const winners=(userData.metrics||[]).filter(m=>m.performanceLabel==='winner'||m.manualWinner);return `<section class="winner-section"><div class="top-videos-heading"><h3>Contenido ganador</h3><span>${winners.length?`${winners.length} detectados`:'En aprendizaje'}</span></div>${winners.length?`<div class="winner-list">${winners.slice(0,8).map(m=>`<article class="winner-card"><span class="winner-badge">GANADOR</span><b>${esc(m.title||'Reel sin título')}</b><small>${numberText(m.views)} vistas · ${esc(m.date||'sin fecha')}</small><p>${esc(m.hypothesis||'Hipótesis pendiente de revisar.')}</p></article>`).join('')}</div>`:'<p class="empty-state">Sincroniza más Reels para detectar tus primeros ganadores.</p>'}</section>`}
function autoLinkMetrics(){const scripts=userData.scripts||[];for(const m of userData.metrics||[]){if(m.linkedScriptId||!m.title)continue;const words=String(m.title).toLowerCase().split(/[^a-záéíóúñ0-9]+/).filter(w=>w.length>4);let best=null,bestScore=0;for(const s of scripts){const hay=String([s.hook,s.title,s.angle].join(' ')).toLowerCase();const hits=words.filter(w=>hay.includes(w)).length;const dateGap=Math.abs(new Date(m.date||0)-new Date(s.recordedAt||s.createdAt||0))/86400000;const score=hits/Math.max(1,words.length)+(dateGap<8?.18:0);if(score>bestScore){bestScore=score;best=s}}if(best&&bestScore>=.25){m.linkedScriptId=best.id;m.linkConfidence=Math.min(99,Math.round(bestScore*100))}}}
function reelLinkingSection(){const unlinked=(userData.metrics||[]).filter(m=>!m.linkedScriptId).slice(0,12);return `<section class="reel-linking-section"><div class="top-videos-heading"><h3>Vincular Reels con guiones</h3><span>${unlinked.length?'Revisión rápida':'Todo vinculado'}</span></div>${unlinked.length?`<div class="linking-list">${unlinked.map(m=>`<label class="linking-row"><span>${esc((m.title||'Reel sin título').slice(0,100))}<small>${esc(m.date||'sin fecha')}</small></span><select class="metric-script-link" data-metric-script-link="${esc(m.id)}"><option value="">Sin vincular</option>${(userData.scripts||[]).map(s=>`<option value="${esc(s.id)}">${esc((s.hook||s.title||'Guion').slice(0,90))}</option>`).join('')}</select></label>`).join('')}</div>`:'<p class="empty-state">No hay Reels pendientes de vincular.</p>'}</section>`}
function winnerSection(){const winners=(userData.metrics||[]).filter(m=>m.performanceLabel==='winner'||m.manualWinner),patterns=userData.patterns||[];return `<section class="winner-section"><div class="top-videos-heading"><h3>Contenido ganador</h3><span>${winners.length?`${winners.length} detectados`:'En aprendizaje'}</span></div>${winners.length?`<div class="winner-list">${winners.slice(0,12).map(m=>`<article class="winner-card"><div class="winner-card-head"><span class="winner-badge">GANADOR</span><label class="manual-winner"><input type="checkbox" class="manual-winner-toggle" data-metric-manual="${esc(m.id)}" ${m.manualWinner?'checked':''}> Marcar manualmente</label></div><b>${esc(m.title||'Reel sin título')}</b><small>${numberText(m.views)} vistas · ${esc(m.date||'sin fecha')}</small><label>Hipótesis<textarea class="metric-hypothesis" data-metric-hypothesis="${esc(m.id)}" rows="2" placeholder="Qué crees que hizo funcionar este video…">${esc(m.hypothesis||'')}</textarea></label><label>Guion relacionado<select class="metric-script" data-metric-script="${esc(m.id)}"><option value="">Sin vincular</option>${(userData.scripts||[]).map(s=>`<option value="${esc(s.id)}" ${m.linkedScriptId===s.id?'selected':''}>${esc((s.hook||s.title||'Guion').slice(0,80))}</option>`).join('')}</select></label></article>`).join('')}</div>`:'<p class="empty-state">Sincroniza más Reels para detectar tus primeros ganadores.</p>'}<div class="patterns-box"><b>Aprendizajes guardados</b><div class="patterns-list">${patterns.map((p,i)=>`<div class="saved-pattern"><span>${esc(p)}</span><button class="text-button delete-pattern" data-pattern-index="${i}">Eliminar</button></div>`).join('')||'<small>Aún no has guardado patrones.</small>'}</div><div class="pattern-add"><input id="newPattern" placeholder="Ej. Los B-roll de ConnAI generan más visitas al perfil"><button class="button button-outline" id="savePattern">Guardar aprendizaje</button></div></div></section>`}
