function patternSummarySection(){const winners=(userData.metrics||[]).filter(m=>m.performanceLabel==='winner'||m.manualWinner),byP={},byF={};for(const m of winners){const p=pillarName(m.pillar||'unclassified');byP[p]=(byP[p]||0)+1;const s=userData.scripts?.find(x=>x.id===m.linkedScriptId),f=s?.format||m.format||'Sin formato';byF[f]=(byF[f]||0)+1}const top=(obj)=>Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,3);return `<section class="pattern-summary"><div class="top-videos-heading"><h3>Patrones detectados</h3><span>${winners.length} ganadores analizados</span></div>${winners.length?`<div class="pattern-columns"><div><small>Pilares con mejor rendimiento</small>${top(byP).map(([k,v])=>`<p><b>${v}</b> · ${esc(k)}</p>`).join('')||'<p>Sin datos</p>'}</div><div><small>Formatos con mejor rendimiento</small>${top(byF).map(([k,v])=>`<p><b>${v}</b> · ${esc(k)}</p>`).join('')||'<p>Sin datos</p>'}</div></div><p class="muted-intro">Esto muestra una señal inicial, no una conclusión definitiva. Aumentará su precisión a medida que publiques más.</p>`:'<p class="empty-state">Cuando existan ganadores vinculados, aparecerán aquí los patrones por pilar y formato.</p>'}</section>`}
function refreshCurrentBrandContext(){const base=userData.brandBase||{};base.identity='Benjamin Romero · @benjaromerozl';base.purpose='Documentar cómo construyo ConnAI y mi propia vida: negocios, aprendizaje, IA, mentalidad y rendimiento.';base.saas='ConnAI: agentes de IA personalizados para atención al cliente por WhatsApp e Instagram. Estado actual: buscando los primeros clientes mediante DMs a negocios locales. Nichos: veterinarias, peluquerías caninas, clínicas dentales y pymes locales.';base.pillars='Pilares activos: Emprendimiento y negocios digitales (sub-pilar: Building in Public — ConnAI), Desarrollo personal y Deporte y rendimiento. Zeeltra está en pausa y no forma parte del contenido actual.';base.formats='Talking head para decisiones, aprendizajes y conversaciones de ConnAI; Green screen para explicar IA, atención al cliente y casos de uso; B-roll + voz en off para documentar el proceso real, DMs, implementaciones y vida personal.';base.updates='Actualización vigente: bio activa “building @connai.ai and my own life.”. ConnAI es el único negocio activo en contenido. No mencionar Zeeltra ni Agenda Viva.';userData.brandBase=base;userData.profileContext=`MARCA PERSONAL ACTUAL\n${base.purpose}\n\nBIO\nbuilding @connai.ai and my own life.\n\nNEGOCIO ACTIVO\n${base.saas}\n\nREGLA\nZeeltra está en pausa; no mencionarlo en contenido.`;userData.saasContext=base.saas;const oldTerms=/zeeltra|agenda viva/i;const pending=userData.hooks.filter(h=>h.status==='new'&&oldTerms.test(String(h.hook||'')+' '+String(h.angle||'')+' '+String(h.framework||'')));if(pending.length){userData.archivedHooks.push(...pending.map(h=>({...h,status:'archived',archivedReason:'Marca actualizada: ConnAI es el único foco activo'})));userData.hooks=userData.hooks.filter(h=>!pending.includes(h))}userData._currentBrandContextVersion=1;userData._needsCloudSeed=true;saveLocal()}
function recomputePerformance(){const ms=userData.metrics||[];const groups={};for(const m of ms){const key=`${m.pillar||'unclassified'}|${m.format||'sin-formato'}`;(groups[key]||(groups[key]=[])).push(m)}for(const m of ms){const group=groups[`${m.pillar||'unclassified'}|${m.format||'sin-formato'}`]||ms,score=x=>Number(x.views||0)+Number(x.reach||0)*.7+Number(x.followersGained||0)*120+Number(x.profileVisits||0)*2+Number(x.comments||0)*8+Number(x.shares||0)*10+Number(x.saves||0)*8,values=group.map(score).filter(Boolean).sort((a,b)=>a-b),mid=values.length?median(values):0,s=score(m);if(m.performanceLabel!=='manual')m.performanceLabel=!values.length?'normal':s>=mid*1.6?'winner':s>=mid*1.15?'promising':s<mid*.55?'low':'normal';if((m.performanceLabel==='winner'||m.manualWinner)&&!m.hypothesis)m.hypothesis='Hipótesis pendiente: revisa hook, formato, tema y cierre.'}}
